.loop_l:
    move.l  d1,d3
    bset  d2,d3
    mulu.w  d3,d3
    cmp.l  d0,d3
    bhi  .skip_l
    bset  d2,d1
.skip_l:
    subq  #1,d2
    bpl  .loop_l
.done_l:
    move.w  d1,d0
    rts

